49	const HOST_RE = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/;
50	
51	async function ownedDomain(domainId: string) {
52	  const user = await requireUser();
53	  const domain = await db.domain.findUnique({ where: { id: domainId } });
54	  if (!domain) throw new Error("Not found");
55	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
56	  return { user, domain };
