247	/* ------------------------------------------------------------------ *
248	 * Reset DNS to a sane default set (strong confirm handled in the UI).
249	 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
250	 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
251	 * ------------------------------------------------------------------ */
252	
253	export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
254	  let ctx;
255	  try {
256	    ctx = await ownedActiveDomain(domainId);
257	  } catch (e) {
258	    return { error: errMsg(e) };
259	  }
260	  const ip = process.env.PUBLIC_IP;
261	  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
262	  let removed = 0;
263	  const failed: { record: string; reason: string }[] = [];
264	  try {
265	    const recs = await listRecords(ctx.domain.name);
266	    for (const r of recs) {
267	      if (!removable.has(r.type)) continue;
268	      try {
269	        await deleteRecord(ctx.domain.name, r.id);
270	        removed++;
271	      } catch (e) {
272	        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
273	      }
274	    }
275	  } catch (e) {
276	    return { error: `Could not read current records: ${errMsg(e)}` };
277	  }
278	
279	  const added: string[] = [];
280	  if (ip) {
281	    for (const host of ["", "www"]) {
282	      try {
283	        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
284	        added.push(`A ${host || "@"} → ${ip}`);
285	      } catch (e) {
286	        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
287	      }
288	    }
289	  }
290	
291	  await db.auditLog.create({
292	    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
293	  });
294	  revalidatePath(`/dashboard/domains/${domainId}`);
295	  return {
296	    added,
297	    skipped: [],
298	    failed: failed.length ? failed : undefined,
299	    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
300	  };
301	}
