// ---------- Nameservers / registrar lock / outbound-transfer auth code ----------
//
// Consolidated out of lib/actions-domains-advanced.ts and
// lib/actions-domains-dns.ts, which each had their own private name.com
// client hitting these same endpoints. `lockDomain`/`unlockDomain` are
// shared by both files: advanced.ts's outbound-transfer flow only ever
// unlocks, dns.ts's registrar-lock toggle does both.

export async function setNameservers(domain: string, nameservers: string[]): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:setNameservers`, { nameservers });
}

export async function lockDomain(domain: string): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:lock`, {});
}

export async function unlockDomain(domain: string): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:unlock`, {});
}

/** Current registrar-lock state, read straight off the domain resource. */
export async function isDomainLocked(domain: string): Promise<boolean> {
  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
  return json?.locked === true;
}

/** EPP/auth code for an outbound transfer. Null when the registrar has none to give. */
export async function getAuthCode(domain: string): Promise<string | null> {
  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getAuthCode`);
  return json?.authCode ? String(json.authCode) : null;
}

