// ---------- URL forwarding ----------
//
// Consolidated out of lib/actions-domains-dns.ts's private client.

export type UrlForward = { host: string; forwardsTo: string; type: string };

export async function listUrlForwarding(domain: string): Promise<UrlForward[]> {
  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/url/forwarding`);
  return (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
    host: f.host ?? "",
    forwardsTo: f.forwardsTo ?? "",
    type: f.type ?? "redirect301",
  }));
}

export async function addUrlForwarding(domain: string, fwd: UrlForward): Promise<void> {
  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/url/forwarding`, fwd);
}

export async function deleteUrlForwarding(domain: string, host: string): Promise<void> {
  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/url/forwarding/${encodeURIComponent(host)}`);
}

