1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import {
8	  registrarConfigured,
9	  listRecords,
10	  addRecord,
11	  deleteRecord,
12	  type DnsRecord,
13	  lockDomain,
14	  unlockDomain,
15	  isDomainLocked,
16	  listUrlForwarding,
17	  addUrlForwarding,
18	  deleteUrlForwarding,
19	} from "./registrar";
20	
21	/* ------------------------------------------------------------------ *
22	 * DNS super-manager actions for the customer domain manager.
23	 *
24	 * Reuses lib/registrar.ts's DNS helpers (listRecords/addRecord/
25	 * deleteRecord) for all record mutations, plus its URL-forwarding and
26	 * registrar-lock helpers. Everything is ownership-checked and degrades
27	 * gracefully (persist intent + a clear note) when the registrar isn't
28	 * configured or a TLD/endpoint isn't supported.
29	 * ------------------------------------------------------------------ */
30	
31	function errMsg(e: unknown): string {
32	  return String(e instanceof Error ? e.message : e).slice(0, 200);
33	}
34	
35	async function ownedDomain(domainId: string) {
36	  const user = await requireUser();
37	  const domain = await db.domain.findUnique({ where: { id: domainId } });
38	  if (!domain) throw new Error("Not found");
39	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
40	  return { user, domain };
41	}
42	
43	async function ownedActiveDomain(domainId: string) {
44	  const ctx = await ownedDomain(domainId);
45	  if (ctx.domain.status !== "ACTIVE") throw new Error("Domain is not active");
46	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
47	  return ctx;
48	}
49	
50	/* A record shape the client can build for presets / imports. Host "" = apex. */
51	export type RecordInput = {
52	  host: string;
53	  type: string;
54	  answer: string;
55	  ttl?: number;
56	  priority?: number;
57	};
58	
59	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
60	
61	function normHost(h: string): string {
62	  const t = (h ?? "").trim();
63	  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
64	}
65	
66	/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
67	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
68	  const wh = normHost(want.host);
69	  const wa = want.answer.trim().toLowerCase();
70	  return existing.some((r) => {
71	    if (r.host !== wh) return false;
72	    if (r.type !== want.type) return false;
73	    if (r.answer.trim().toLowerCase() !== wa) return false;
74	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
75	    return true;
76	  });
77	}
78	
79	const recordInputSchema = z.object({
80	  host: z.string().max(120).default(""),
81	  type: z.enum(RECORD_TYPES),
82	  answer: z.string().min(1).max(2000),
83	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
84	  priority: z.coerce.number().int().min(0).max(65535).optional(),
85	});
86	
87	export type BulkResult = {
88	  error?: string;
89	  added?: string[];
90	  skipped?: string[];
91	  failed?: { record: string; reason: string }[];
92	  note?: string;
93	};
94	
95	function label(r: RecordInput): string {
96	  const h = normHost(r.host) || "@";
97	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
98	  return `${r.type} ${h} → ${pri}${r.answer}`;
99	}
100	
101	/**
102	 * Add many DNS records at once, skipping any that already exist. Powers the
103	 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
104	 */
105	export async function addDnsRecordsBulk(
106	  domainId: string,
107	  records: RecordInput[]
108	): Promise<BulkResult> {
109	  let ctx;
110	  try {
111	    ctx = await ownedActiveDomain(domainId);
112	  } catch (e) {
113	    return { error: errMsg(e) };
114	  }
115	  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
116	  if (records.length > 100) return { error: "Too many records in one request (max 100)." };
117	
118	  const clean: RecordInput[] = [];
119	  for (const raw of records) {
120	    const parsed = recordInputSchema.safeParse(raw);
121	    if (!parsed.success) {
122	      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
123	    }
124	    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
125	  }
126	
127	  let existing: DnsRecord[];
128	  try {
129	    existing = await listRecords(ctx.domain.name);
130	  } catch (e) {
131	    return { error: `Could not read current records: ${errMsg(e)}` };
132	  }
133	
134	  const added: string[] = [];
135	  const skipped: string[] = [];
136	  const failed: { record: string; reason: string }[] = [];
137	
138	  for (const rec of clean) {
139	    if (recordExists(existing, rec)) {
140	      skipped.push(label(rec));
141	      continue;
142	    }
143	    try {
144	      await addRecord(ctx.domain.name, {
145	        host: rec.host,
146	        type: rec.type,
147	        answer: rec.answer,
148	        ttl: rec.ttl ?? 300,
149	        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
150	      });
151	      added.push(label(rec));
152	      // Track locally so later records in the same batch dedupe correctly.
153	      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
154	    } catch (e) {
155	      failed.push({ record: label(rec), reason: errMsg(e) });
156	    }
157	  }
158	
159	  await db.auditLog.create({
160	    data: {
161	      userId: ctx.user.id,
162	      action: "domain.dns_bulk_add",
163	      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
164	    },
165	  });
166	  revalidatePath(`/dashboard/domains/${domainId}`);
167	  return { added, skipped, failed: failed.length ? failed : undefined };
168	}
169	
170	/* ------------------------------------------------------------------ *
171	 * DNS import (paste) — CSV / zone-ish text: name,type,value[,ttl[,priority]]
172	 * Lines starting with # or ; are ignored. Whitespace or comma separated.
173	 * ------------------------------------------------------------------ */
174	
175	export type ParsedImport = { records: RecordInput[]; errors: string[] };
176	
177	/** Pure parser exported so the UI can preview before applying. */
178	export async function parseDnsImport(text: string): Promise<ParsedImport> {
179	  const records: RecordInput[] = [];
180	  const errors: string[] = [];
181	  const lines = (text ?? "").split(/\r?\n/);
182	  lines.forEach((line, i) => {
183	    const raw = line.trim();
184	    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
185	    // split on comma OR whitespace, but keep the value token intact if quoted
186	    let parts: string[];
187	    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
188	    else parts = raw.split(/\s+/);
189	    if (parts.length < 3) {
190	      errors.push(`Line ${i + 1}: expected at least name, type, value`);
191	      return;
192	    }
193	    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
194	    const type = typeTok.toUpperCase();
195	    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
196	      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
197	      return;
198	    }
199	    const value = valueTok.replace(/^"|"$/g, "");
200	    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
201	    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
202	    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
203	    records.push(rec);
204	  });
205	  return { records, errors };
206	}
207	
208	export async function importDnsRecords(domainId: string, text: string): Promise<BulkResult> {
209	  const { records, errors } = await parseDnsImport(text);
210	  if (errors.length && records.length === 0) {
211	    return { error: errors.join("; ").slice(0, 300) };
212	  }
213	  const res = await addDnsRecordsBulk(domainId, records);
214	  if (errors.length) {
215	    res.note = `${errors.length} line(s) skipped: ${errors.slice(0, 3).join("; ")}${errors.length > 3 ? "…" : ""}`;
216	  }
217	  return res;
218	}
219	
220	/* ------------------------------------------------------------------ *
221	 * Reset DNS to a sane default set (strong confirm handled in the UI).
222	 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
223	 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
224	 * ------------------------------------------------------------------ */
225	
226	export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
227	  let ctx;
228	  try {
229	    ctx = await ownedActiveDomain(domainId);
230	  } catch (e) {
231	    return { error: errMsg(e) };
232	  }
233	  const ip = process.env.PUBLIC_IP;
234	  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
235	  let removed = 0;
236	  const failed: { record: string; reason: string }[] = [];
237	  try {
238	    const recs = await listRecords(ctx.domain.name);
239	    for (const r of recs) {
240	      if (!removable.has(r.type)) continue;
241	      try {
242	        await deleteRecord(ctx.domain.name, r.id);
243	        removed++;
244	      } catch (e) {
245	        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
246	      }
247	    }
248	  } catch (e) {
249	    return { error: `Could not read current records: ${errMsg(e)}` };
250	  }
251	
252	  const added: string[] = [];
253	  if (ip) {
254	    for (const host of ["", "www"]) {
255	      try {
256	        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
257	        added.push(`A ${host || "@"} → ${ip}`);
258	      } catch (e) {
259	        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
260	      }
261	    }
262	  }
263	
264	  await db.auditLog.create({
265	    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
266	  });
267	  revalidatePath(`/dashboard/domains/${domainId}`);
268	  return {
269	    added,
270	    skipped: [],
271	    failed: failed.length ? failed : undefined,
272	    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
273	  };
274	}
275	
276	/* ------------------------------------------------------------------ *
277	 * URL forwarding / redirects (name.com URL-forwarding API).
278	 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
279	 * Degrades to a persisted-intent Setting + note when unconfigured.
280	 * ------------------------------------------------------------------ */
281	
282	export type Redirect = { host: string; forwardsTo: string; type: string };
283	
284	const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;
285	
286	async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
287	  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
288	  if (!s?.value) return [];
289	  try {
290	    const parsed = JSON.parse(s.value);
291	    return Array.isArray(parsed) ? parsed : [];
292	  } catch {
293	    return [];
294	  }
295	}
296	
297	async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
298	  await db.setting.upsert({
299	    where: { key: redirectStoreKey(domainId) },
300	    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
301	    update: { value: JSON.stringify(list) },
302	  });
303	}
304	
305	export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };
306	
307	/** List forwardings — live from name.com when possible, else persisted intent. */
308	export async function listRedirects(domainId: string): Promise<RedirectsView> {
309	  let ctx;
310	  try {
311	    ctx = await ownedDomain(domainId);
312	  } catch (e) {
313	    return { forwards: [], live: false, error: errMsg(e) };
314	  }
315	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
316	    try {
317	      const forwards = await listUrlForwarding(ctx.domain.name);
318	      return { forwards, live: true };
319	    } catch (e) {
320	      // Fall back to intent store but tell the truth about why.
321	      const forwards = await readRedirectIntent(domainId);
322	      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
323	    }
324	  }
325	  const forwards = await readRedirectIntent(domainId);
326	  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
327	}
328	
329	const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;
330	
331	export async function setRedirect(
332	  domainId: string,
333	  hostRaw: string,
334	  forwardsTo: string,
335	  type: string
336	): Promise<RedirectsView> {
337	  let ctx;
338	  try {
339	    ctx = await ownedDomain(domainId);
340	  } catch (e) {
341	    return { forwards: [], live: false, error: errMsg(e) };
342	  }
343	  const host = normHost(hostRaw);
344	  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
345	  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
346	  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };
347	
348	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
349	  if (canLive) {
350	    try {
351	      // Upsert: delete any existing forwarding for this host, then create.
352	      try {
353	        await deleteUrlForwarding(ctx.domain.name, host);
354	      } catch {
355	        /* none existed */
356	      }
357	      await addUrlForwarding(ctx.domain.name, { host, forwardsTo: url.data, type: t });
358	    } catch (e) {
359	      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
360	    }
361	  } else {
362	    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
363	    list.push({ host, forwardsTo: url.data, type: t });
364	    await writeRedirectIntent(domainId, list);
365	  }
366	
367	  await db.auditLog.create({
368	    data: { userId: ctx.user.id, action: "domain.redirect_set", detail: `${ctx.domain.name} ${host || "@"} -> ${url.data} (${t})${canLive ? " live" : " intent"}` },
369	  });
370	  revalidatePath(`/dashboard/domains/${domainId}`);
371	  const view = await listRedirects(domainId);
372	  return {
373	    ...view,
374	    note: canLive
375	      ? "Redirect saved at name.com via URL forwarding. It can take a little while to take effect."
376	      : "Saved. This redirect will be applied via name.com URL forwarding once the domain is active and the registrar is connected.",
377	  };
378	}
379	
380	export async function deleteRedirect(domainId: string, hostRaw: string): Promise<RedirectsView> {
381	  let ctx;
382	  try {
383	    ctx = await ownedDomain(domainId);
384	  } catch (e) {
385	    return { forwards: [], live: false, error: errMsg(e) };
386	  }
387	  const host = normHost(hostRaw);
388	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
389	  if (canLive) {
390	    try {
391	      await deleteUrlForwarding(ctx.domain.name, host);
392	    } catch (e) {
393	      return { ...(await listRedirects(domainId)), error: `Could not remove redirect: ${errMsg(e)}` };
394	    }
395	  }
396	  const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
397	  await writeRedirectIntent(domainId, list);
398	  await db.auditLog.create({
399	    data: { userId: ctx.user.id, action: "domain.redirect_delete", detail: `${ctx.domain.name} ${host || "@"}` },
400	  });
401	  revalidatePath(`/dashboard/domains/${domainId}`);
402	  return { ...(await listRedirects(domainId)), note: "Redirect removed." };
403	}
404	
405	/* ------------------------------------------------------------------ *
406	 * Registrar lock (name.com :lock / :unlock). Persist state + note.
407	 * ------------------------------------------------------------------ */
408	
409	const lockStoreKey = (domainId: string) => `domain-lock:${domainId}`;
410	
411	export type LockView = { locked: boolean; live: boolean; note?: string; error?: string };
412	
413	export async function getRegistrarLock(domainId: string): Promise<LockView> {
414	  let ctx;
415	  try {
416	    ctx = await ownedDomain(domainId);
417	  } catch (e) {
418	    return { locked: false, live: false, error: errMsg(e) };
419	  }
420	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
421	    try {
422	      const locked = await isDomainLocked(ctx.domain.name);
423	      return { locked, live: true };
424	    } catch {
425	      /* fall through to stored intent */
426	    }
427	  }
428	  const s = await db.setting.findUnique({ where: { key: lockStoreKey(domainId) } });
429	  return { locked: s?.value === "true", live: false };
430	}
431	
432	export async function setRegistrarLock(domainId: string, locked: boolean): Promise<LockView> {
433	  let ctx;
434	  try {
435	    ctx = await ownedDomain(domainId);
436	  } catch (e) {
437	    return { locked: false, live: false, error: errMsg(e) };
438	  }
439	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
440	  let live = false;
441	  let note: string | undefined;
442	  if (canLive) {
443	    try {
444	      if (locked) {
445	        await lockDomain(ctx.domain.name);
446	      } else {
447	        await unlockDomain(ctx.domain.name);
448	      }
449	      live = true;
450	      note = locked
451	        ? "Registrar lock enabled — the domain is protected against unauthorized transfers."
452	        : "Registrar lock disabled — the domain can now be transferred to another registrar.";
453	    } catch (e) {
454	      return { locked: !locked, live: false, error: `Registrar rejected the change: ${errMsg(e)}. Some TLDs manage the lock manually.` };
455	    }
456	  } else {
457	    note = "Saved. This lock preference will be applied at name.com once the domain is active and the registrar is connected.";
458	  }
459	  await db.setting.upsert({
460	    where: { key: lockStoreKey(domainId) },
461	    create: { key: lockStoreKey(domainId), value: String(locked) },
462	    update: { value: String(locked) },
463	  });
464	  await db.auditLog.create({
465	    data: { userId: ctx.user.id, action: "domain.registrar_lock", detail: `${ctx.domain.name} -> ${locked ? "locked" : "unlocked"}${live ? " (live)" : ""}` },
466	  });
467	  revalidatePath(`/dashboard/domains/${domainId}`);
468	  return { locked, live, note };
469	}
